CREATE TABLE IF NOT EXISTS assessment_questions(id varchar(64) PRIMARY KEY,bank_id varchar(64) NOT NULL,course_id varchar(64) NOT NULL,chapter_id varchar(64),kind varchar(24) NOT NULL,prompt text NOT NULL,choices json NOT NULL,correct json NOT NULL,explanation text NOT NULL,source_pages json NOT NULL,provenance_sha256 varchar(64) NOT NULL,difficulty integer NOT NULL CHECK(difficulty BETWEEN 1 AND 5),approved integer NOT NULL CHECK(approved IN(0,1)),points integer NOT NULL CHECK(points BETWEEN 1 AND 100));
CREATE INDEX IF NOT EXISTS ix_assessment_questions_course ON assessment_questions(course_id,approved,difficulty);
CREATE TABLE IF NOT EXISTS assessment_blueprints(id varchar(64) PRIMARY KEY,title varchar(180) NOT NULL,course_id varchar(64) NOT NULL,duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 5 AND 360),question_count integer NOT NULL CHECK(question_count BETWEEN 1 AND 200),pass_percent integer NOT NULL CHECK(pass_percent BETWEEN 0 AND 100),shuffle integer NOT NULL,approved_only integer NOT NULL,row_version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS assessment_attempts(id varchar(64) PRIMARY KEY,account_id varchar(64) NOT NULL,blueprint_id varchar(64) NOT NULL,question_ids json NOT NULL,started_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,state varchar(24) NOT NULL CHECK(state IN('active','submitted','graded','abandoned')),answers json NOT NULL,submitted_at timestamptz,row_version integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS ix_assessment_attempt_account_state ON assessment_attempts(account_id,state,started_at DESC);
CREATE TABLE IF NOT EXISTS assessment_results(attempt_id varchar(64) PRIMARY KEY,earned integer NOT NULL,possible integer NOT NULL,percent integer NOT NULL CHECK(percent BETWEEN 0 AND 100),passed integer NOT NULL CHECK(passed IN(0,1)),by_chapter json NOT NULL,questions json NOT NULL);
